【図解】JV運営で押さえる3点
　★①対発注者：構成員は連帯して責任を負う（内部事情は主張できない）
　★②対内部：協定書・運営に関する取決めが優先。口約束は効かない
　★③意思決定：運営委員会の決議と議事録。記録がなければ後で覆る
　○もめたときに開くのは、感情ではなく協定書
　×「現場の力関係」で決めると、必ず後で紛争になる★
