        body: `▼ゼロから
CV・SVは「いくら」の話でしたが、大きな工事では金額だけでは深刻さが分かりません。
そこで比率にします。CPIとSPIです。
2つの数字の組合せで、現場の状態が4通りに分類できます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 ①【例題】数値条件
━━━━━━━━━━━━━━━━━━━━━━
・前セクションと同じ工事（単位：千円）
　　BAC ＝ 432,000／PV ＝ 120,000／EV ＝ 108,000／AC ＝ 115,000
・次を求めよ。
　　(1) CPI（コスト効率指数）
　　(2) SPI（スケジュール効率指数）
　　(3) 4象限のどこに位置するか
　　(4) TCPI（残作業に必要なコスト効率）
　　(5) 現場に出すべき指示

━━━━━━━━━━━━━━━━━━━━━━
🔑 ②【考え方】どの式を使うか
━━━━━━━━━━━━━━━━━━━━━━
・指数はどちらも「EV ÷ 何か」である★
　　CPI ＝ EV ÷ AC　（1円の支出で、いくらの出来高を稼げたか）
　　SPI ＝ EV ÷ PV　（計画した出来高の何割を達成したか）
・判定
　　1.0 より大きい → 良好
　　1.0 → 計画どおり
　　1.0 より小さい → 不良★
・CVとCPIの違い
　　CV：金額（規模の情報を含む）
　　CPI：比率（効率の情報。工事規模に依存しないので比較できる）★
・TCPI（To Complete Performance Index）
　　TCPI ＝（BAC − EV）÷（BAC − AC）
　　残りの予算で完成させるために必要な、今後のコスト効率★
　　→ 現在のCPIより大きければ、「今より良くしないと予算内に収まらない」

【図解】CPI・SPIの4象限（現場診断の型）
　　　　　　　SPI≧1（進捗良好）　　SPI＜1（進捗遅延）
　CPI≧1　　　○理想（良好）　　　　△原価は良いが遅い
　（原価良好）　　　　　　　　　　　　→ 増員・工程回復を検討
　CPI＜1　　　△早いが高い　　　　　★最悪（本例）
　（原価超過）　→ 原価の締め直し　　　→ 原価・工程の同時対策★
　○CPIとSPIは必ず2つセットで見る
　×CPIだけ、SPIだけを見て判断すると対策を誤る★
　→ 象限を特定してから、対策を選ぶ

━━━━━━━━━━━━━━━━━━━━━━
🔑 ③【解答】途中式
━━━━━━━━━━━━━━━━━━━━━━
・(1) CPI
　　　CPI ＝ EV ÷ AC ＝ 108,000 ÷ 115,000
　　　　　＝ 0.939130… → ★約0.94
　　　検算：AC × CPI ＝ 115,000 × 0.93913 ＝ 108,000 ○一致★
　　　意味：1円の支出で 0.94円分の出来高しか稼げていない
・(2) SPI
　　　SPI ＝ EV ÷ PV ＝ 108,000 ÷ 120,000 ＝ 0.90 → ★0.90
　　　検算：PV × SPI ＝ 120,000 × 0.90 ＝ 108,000 ○一致★
　　　意味：計画出来高の90%しか達成していない
・(3) 象限の判定
　　　CPI 0.94 ＜ 1.0（原価超過）
　　　SPI 0.90 ＜ 1.0（進捗遅延）
　　　★→ 両方が1.0未満。最も注意を要する象限（原価も工程も悪化）
・(4) TCPI
　　　TCPI ＝（BAC − EV）÷（BAC − AC）
　　　　　　＝（432,000 − 108,000）÷（432,000 − 115,000）
　　　　　　＝ 324,000 ÷ 317,000 ＝ 1.02208… → ★約1.022
　　　意味：残作業を、今後は 1.022 の効率でこなさないと BAC に収まらない
　　　★現在のCPIは 0.94。1.022 まで引き上げる必要があり、容易ではない
　　　検算：317,000 × 1.02208 ＝ 324,000 ○一致★
・(5) 現場への指示
　　　○原価面：CPI 0.94 の原因を費目別に分解する（数量差異／価格差異）
　　　○工程面：SPI 0.90 の遅れがクリティカルパス上か確認する
　　　★両方が悪い場合、工程回復のための増員は CPI をさらに悪化させる
　　　　→ 「工程優先か原価優先か」を、EAC（次セクション）で試算して決める★

【図解】CPIとCVの使い分け
　　CV ＝ −7,000千円　→ 「金額でいくら悪いか」（対策の規模を決める）
　★CPI ＝ 0.94　　　 → 「どれくらい効率が悪いか」（他工事と比較できる）
　○社内で工事間を比較するならCPI、資金計画を組むならCV
　×「CVが小さいから軽微」と判断すると、大工事では手遅れになる★
　　（本例は進捗25%時点で CPI 0.94。この効率が続けば完成時の超過は数万千円規模）
　→ 金額と比率は、目的が違う道具

⚠ ひっかけ注意
・CPI・SPIは、どちらも分子がEVである。分母を取り違えないこと★
・SPIは工期終盤に必ず1.0へ収束する（EVもPVもBACに近づく）。
　　したがって終盤のSPIは遅延の指標として機能しにくい★
・CPI・SPIが1.0を超えていても、品質・安全を犠牲にしていないかは別途確認する。
・指数は「今までの累積」を表す。直近の傾向を見るには期間別に算出する★

━━━━━━━━━━━━━━━━━━━━━━
🔑 ④【類題のポイント】一般化
━━━━━━━━━━━━━━━━━━━━━━
・数値が変わっても、式は3本★
　　CPI ＝ EV ÷ AC／SPI ＝ EV ÷ PV／TCPI ＝（BAC − EV）÷（BAC − AC）
・逆算も頻出。
　　例：CPI ＝ 0.90、EV ＝ 90,000 のとき AC は？
　　　　AC ＝ EV ÷ CPI ＝ 90,000 ÷ 0.90 ＝ 100,000千円★
・CV・SVとCPI・SPIは符号と大小が対応する。
　　CV＜0 ⇔ CPI＜1／SV＜0 ⇔ SPI＜1（必ず一致する）★
・結論の骨は「金額はCV・SV、効率はCPI・SPI、必要努力はTCPI」。`,
